// @ts-check
// Plain-language help. One source for the "?" tooltips and the searchable Help panel.
// Written to ASD-STE100 (Simplified Technical English): short sentences, active voice, one instruction per sentence,
// imperatives for actions, common words. Each entry: what it is, why it is important, and what to do.

/** @typedef {{ t: string, what: string, why?: string, tip?: string, group: string, later?: boolean }} Help
 *  later: the control is in the code but not shown yet; the Help panel lists the entry only with ?later=1. */

